<?php
require_once __DIR__.'/includes/bootstrap.php';require_role(['admin','receptionniste','accueil','caissier']);$page_title='Factures & paiements';$rows=db()->query("SELECT p.*,o.reference AS code,c.nom,c.prenom FROM paiements p JOIN commandes o ON o.id=p.commande_id JOIN clients c ON c.id=o.client_id ORDER BY p.id DESC LIMIT 500")->fetchAll();require 'includes/header.php';?>
<div class="panel"><div class="panel-head"><h2>Historique des encaissements</h2><input class="search" data-filter="#payments" placeholder="Rechercher..."></div><div class="table-wrap"><table id="payments"><thead><tr><th>Date</th><th>Reçu commande</th><th>Client</th><th>Mode</th><th>Référence</th><th>Montant encaissé</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=date('d/m/Y H:i',strtotime($r['date_paiement']))?></td><td><a href="order_view.php?id=<?=(int)$r['commande_id']?>"><?=e($r['code'])?></a></td><td><?=e($r['prenom'].' '.$r['nom'])?></td><td><?=e($r['mode'])?></td><td><?=e($r['reference'])?></td><td><b><?=money($r['montant'])?></b></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="6" class="empty">Aucun paiement enregistré.</td></tr><?php endif;?></tbody></table></div></div><?php require 'includes/footer.php';?>
